The `scpn_quantum_control.kuramoto_core` facade is the stable entry point for
users who only need the Kuramoto-XY compiler layer:

1. provide an arbitrary symmetric coupling matrix `K_nm`;
2. provide heterogeneous natural frequencies `omega`;
3. compile a Hamiltonian or Trotter circuit;
4. evaluate the Kuramoto order parameter from a statevector;
5. run higher-order, monitored, or PT-symmetric trajectory variants;
6. attach serialisable provenance metadata to downstream result artifacts.

The facade deliberately avoids SCPN-specific constants. Domain pipelines such as
power-grid, EEG, plasma, or connectome workflows should compile their source data
into `K_nm` and `omega`, then call this layer.

## Validation Contract

`build_kuramoto_problem()` fails loudly if:

- `K_nm` is not square;
- `K_nm` is empty;
- `omega` does not have shape `(N,)`;
- either array would require implicit string, boolean, object, or complex
  coercion before it can be interpreted as real numeric data;
- either array contains non-finite values;
- `K_nm` is asymmetric;
- metadata cannot be JSON-serialised.

The diagonal of `K_nm` is set to zero. Inputs are copied and made read-only so
later caller-side mutation cannot alter the compiled problem.

## Unsupported boundaries

Unsupported does not mean ignored. Current public boundaries include:

- arbitrary Python/NumPy program AD beyond supported trace operations;
- full native compiler AD for every MLIR/LLVM/JIT path;
- complete gradient tape semantics beyond supported phase parameter-shift and QNode-style phase records;
- first-path namespace routes outside `scpn_quantum_control.diff` and `scpn.diff`
  when they bypass `DifferentiableCircuitDiagnostics`, `ShotPolicy`, and
  explicit fail-closed JIT explanation metadata;
- public JAX/PyTorch/TensorFlow adapters beyond the documented bounded-model and deterministic registered statevector routes;
- hardware gradient jobs without hardware-gradient policy approval, required evidence IDs, and live-execution ticketing where applicable;
- provider callbacks that omit finite-shot variance or shifted-sample provenance;
- unsupported gate, observable, transform, adapter, or backend combinations returned by `plan_gradient_support(...)`;
- unsupported transform nesting returned by `plan_gradient_transform_nesting(...)`;
- arbitrary quantum neural architectures beyond the bounded local phase-QNN classifier, its QNN-specific gradient verifier, deterministic multi-seed envelope, bounded loss-landscape scans, finite-shot simulator evidence, conformance, convergence, framework-agreement, and named optimizer-baseline suites, and declared QSNN training routes;
- gates without registered generator spectra;
- dynamic topology changes that invalidate parameter indexing;
- static dense native determinant traces at `20x20` and wider until a stronger determinant-partial helper is verified;
- wide native quotient-linalg traces beyond the documented support profile.

def _probe(name: str) -> Backend | None:
    """Return a working backend handle for ``name``, or ``None`` if unavailable."""
    if name == "numpy":
        return NumpyBackend()
    if name == "rust":
        candidate = RustBackend()
        try:
            candidate.sc_forward(
                np.zeros((1, 1, 1), dtype=np.uint64), np.zeros(1, dtype=np.float64), length=1
            )
        except (ImportError, OSError, RuntimeError, ValueError):
            return None
        return candidate
    return None

class AuditLogger:
    """Append-only JSONL audit log for UPDE simulation steps."""

    def __init__(self, path: str | Path, *, event_stream: str | Path | None = None):
        if not isinstance(path, (str, Path)):
            raise AuditError(f"audit path must be str or Path, got {path!r}")
        if event_stream is not None and not isinstance(event_stream, (str, Path)):
            raise AuditError(
                f"event_stream path must be str, Path, or None, got {event_stream!r}"
            )
        if not str(path).strip():
            raise AuditError("audit path must be a non-empty path")
        if event_stream is not None and not str(event_stream).strip():
            raise AuditError("event_stream path must be non-empty when provided")
        self._path = Path(path)
        if event_stream is not None and _same_file(self._path, Path(event_stream)):
            raise AuditError(
                "audit path and event_stream must be different files: the JSONL "
                "log and the protobuf stream would interleave into one file that "
                f"neither reader can parse ({self._path})"
            )
        if self._path.exists() and self._path.is_dir():
            raise AuditError(
                f"audit path must be a file path, got directory {self._path}"
            )
        self._prev_hash, self._sequence = self._load_previous_state()
        self._audit_key = os.environ.get("SPO_AUDIT_KEY")
        self._stream_id = _DEFAULT_STREAM_ID
        if self._audit_key is not None and self._audit_key == "":
            msg = "SPO_AUDIT_KEY must not be empty"
            raise AuditError(msg)
        if self._audit_key is None and is_production_mode("SPO_AUDIT"):
            raise AuditError(
                "SPO_AUDIT_KEY is required in production mode "
                "(SPO_AUDIT_ENV/SPO_AUDIT_PROFILE or SPO_ENV/SPO_PROFILE = "
                "'production'): refusing to write an unsigned, unverifiable audit "
                "trail. Set SPO_AUDIT_KEY to enable HMAC signing."
            )
        if self._audit_key is not None and self._sequence > 0:
            self._ensure_existing_stream_is_signed()
        self._fh = self._path.open("a", encoding="utf-8", buffering=1)
        self._event_stream = (
            EventStreamWriter(event_stream) if event_stream is not None else None
        )
        self._event_stream_integrity: AuditStreamIntegrityResult | None = None

    def _load_previous_state(self) -> tuple[str, int]:
        """Load the previous audit-chain state from disk, else raise."""
        if not self._path.exists() or self._path.stat().st_size == 0:
            return _ZERO_HASH, 0
        previous = _ZERO_HASH
        sequence = 0
        with self._path.open(encoding="utf-8") as fh:
            for line in fh:
                stripped = line.strip()
                if not stripped:
                    continue
                record = _loads_audit_json(stripped)
                stored = record.get("_hash")
                if isinstance(stored, str) and len(stored) == 64:
                    previous = stored
                stored_sequence = record.get("_audit_sequence")
                if isinstance(stored_sequence, int) and stored_sequence > sequence:
                    sequence = stored_sequence
                else:
                    sequence += 1
        return previous, sequence

    def _ensure_existing_stream_is_signed(self) -> None:
        """Assert an existing audit stream is signed, else raise."""
        with self._path.open(encoding="utf-8") as fh:
            for line_number, line in enumerate(fh, start=1):
                stripped = line.strip()
                if not stripped:
                    continue
                record = _loads_audit_json(stripped)
                if not isinstance(record.get("_signature"), dict):
                    msg = (
                        "SPO_AUDIT_KEY configured but existing audit log "
                        f"contains unsigned record at line {line_number}"
                    )
                    raise AuditError(msg)

    def _write_record(self, record: dict[str, Any]) -> None:
        """Append an audit record to the JSONL log, else raise."""
        if self._event_stream is not None:
            # Refuse before the JSONL line or the signing sequence advances,
            # so the two sinks never diverge on a record the stream rejects.
            try:
                self._event_stream.resolve_event_type(record)
            except ValueError as exc:
                raise AuditError(
                    f"record cannot be sealed into the event stream: {exc}"
                ) from exc
        clean = {k: v for k, v in record.items() if k != "_hash"}
        if self._audit_key is not None:
            clean = self._attach_signature_metadata(clean)
        else:
            clean["_audit_mode"] = "unsigned-development"
            clean["_previous_hash"] = self._prev_hash
            clean["_payload_hash"] = _payload_hash(clean)
        json_line = _dumps_audit_json(clean, compact=True)
        digest = hashlib.sha256((self._prev_hash + json_line).encode()).hexdigest()
        self._prev_hash = digest
        stored = {**clean, "_hash": digest}
        self._fh.write(_dumps_audit_json(stored) + "\n")
        if self._event_stream is not None:
            self._event_stream.write(stored)

    def _attach_signature_metadata(self, clean: dict[str, Any]) -> dict[str, Any]:
        """Attach signature metadata to an audit record."""
        self._sequence += 1
        payload = _payload_without_audit_metadata(clean)
        payload_hash = _payload_hash(payload)
        timestamp_ns = time.time_ns()
        key = self._audit_key
        if key is None:
            msg = "audit key missing during signature construction"
            raise AuditError(msg)
        key_id = key_id_for_secret(key)
        signature_metadata = {
            "algorithm": SIGNATURE_ALGORITHM,
            "key_id": key_id,
        }
        audit_mode = "hmac-signed"
        signing_material = {
            "audit_mode": audit_mode,
            "metadata": signature_metadata,
            "payload_hash": payload_hash,
            "previous_event_hash": self._prev_hash,
            "schema_version": _AUDIT_SCHEMA_VERSION,
            "sequence": self._sequence,
            "stream_id": self._stream_id,
            "timestamp_unix_ns": timestamp_ns,
        }
        signature = hmac.new(
            key.encode(),
            _dumps_audit_json(signing_material, compact=True).encode(),
            hashlib.sha256,
        ).hexdigest()
        return {
            **clean,
            "_audit_schema_version": _AUDIT_SCHEMA_VERSION,
            "_audit_mode": audit_mode,
            "_audit_sequence": self._sequence,
            "_audit_stream_id": self._stream_id,
            "_audit_timestamp_unix_ns": timestamp_ns,
            "_payload_hash": payload_hash,
            "_previous_hash": self._prev_hash,
            "_signature": {
                **signature_metadata,
                "value": signature,
            },
        }

def _decide(
    merge_trace: MergeWindowTrace,
    safety_certificate: KinematicSafetyCertificate,
    bank_feasible: bool,
    bank_reason: str,
) -> tuple[MergeTriggerOutcome, str]:
    if not safety_certificate.passed:
        return (
            MergeTriggerOutcome.ABORT_UNSAFE,
            f"axial-separation envelope violated at sample {safety_certificate.first_violation_index}",
        )
    if not merge_trace.lock_achieved:
        return (
            MergeTriggerOutcome.HOLD_NO_LOCK,
            "no sustained phase-and-spatial lock within the merge window",
        )
    if not bank_feasible:
        return (MergeTriggerOutcome.ABORT_BANK_INFEASIBLE, f"compression pulse infeasible: {bank_reason}")
    return (
        MergeTriggerOutcome.FIRE,
        f"locked and safe at t = {merge_trace.first_lock_time_s} s with a feasible compression pulse",
    )


def _maybe_recovery(scenario: MergeTriggerScenario) -> FaradayRecoveryReport | None:
