def compare_replay_bytes(original: bytes | None, replay: bytes | None) -> ReplayBytes:
    """Compare complete immutable raw outputs without normalizing or parsing them.

    Parameters
    ----------
    original : bytes or None
        Retained original compilation output; None means actual unavailability.
    replay : bytes or None
        Separately retained repeated output, never a repaired original.

    Returns
    -------
    ReplayBytes
        Exact byte observation, without native policy or quantum admission.

    Raises
    ------
    TypeError
        If either supplied output is not immutable bytes or None.

    """
    if (original is not None and type(original) is not bytes) or (
        replay is not None and type(replay) is not bytes
    ):
        raise TypeError("Replay outputs must be immutable bytes or unavailable.")
    left_length = None if original is None else len(original)
    right_length = None if replay is None else len(replay)
    if original is None or replay is None:
        return ReplayBytes("unavailable", left_length, right_length, None)
    for index, (left, right) in enumerate(zip(original, replay, strict=False)):
        if left != right:
            return ReplayBytes("different", left_length, right_length, index)
    if left_length != right_length:
        return ReplayBytes(
            "different", left_length, right_length, min(len(original), len(replay))
        )
    return ReplayBytes("equal", left_length, right_length, None)

